      float sStrength = scanlineStrength * (0.5 + 0.5 * glitchFactor);
      float wave = sin(scanPos * 3.14159 * 2.0 + cc_time.x * 8.0);
      scanline = 1.0 - sStrength * (0.5 + 0.5 * wave);
      scanline *= (0.9 + 0.2 * glitch_noise(vec2(uv0.y * 200.0, cc_time.x * 15.0)));
      scanline = clamp(scanline, 0.6, 1.0);
    }
    o.rgb *= scanline;
    float grain = 1.0;
    if (glitchFactor > 0.1) {
      grain = 0.95 + 0.1 * glitch_noise(vec2(uv0 * 800.0 + cc_time.x * 50.0));
      o.rgb *= grain;
    }
  } else {
    #if TWO_COLORED
      vec4 texColor = texture2D(cc_spriteTexture, uv0);
      originalAlpha = texColor.a;
      o.a = texColor.a * v_light.a;
      o.rgb = ((texColor.a - 1.0) * v_dark.a + 1.0 - texColor.rgb) * v_dark.rgb + texColor.rgb * v_light.rgb;
    #else
      o = texture2D(cc_spriteTexture, uv0);
      originalAlpha = o.a;
      o *= v_light;
    #endif
  }
  o.rgb += tintColor.rgb * tintColor.a * originalAlpha;
  if (enableRainbow) {
    float noise = texture2D(noiseTexture, uv0 * rainbowNoiseScale.xy).r;
    vec3 hsvTorgb = HSVToRGB(vec3((distance(uv0, rainbowCenter.xy) + (noise * rainbowNoiseFactor)) * rainbowDensity + (rainbowSpeed * cc_time.x), 1.0, 1.0));
    vec3 hsvTorgb2 = RGBToHSV(hsvTorgb);
    vec3 hsvTorgb3 = HSVToRGB(vec3(hsvTorgb2.x, rainbowSaturation, hsvTorgb2.z * rainbowBrightness));
    float safePower = abs((o.r + o.r + o.g + o.g + o.g + o.b) / 6.0);
    o.rgb += hsvTorgb3 * rainbowFade * pow(safePower, max(rainbowContrast, 0.001));
  }
  if (enableShifting) {
    float pixelBrightness = (o.r + o.r + o.g + o.g + o.g + o.b) / 6.0;
    float shiftingCycle = mod((pixelBrightness + (cc_time.x * shiftingSpeed)) * shiftingDensity, 1.0);
    vec3 shiftingColor = mix(shiftingColorA.rgb, shiftingColorB.rgb, abs(shiftingCycle - 0.5) * 2.0);
    shiftingColor *= shiftingBrightness;
    vec3 shiftingResult = shiftingColor * pow(max(pixelBrightness, 0.0001), max(shiftingContrast, 0.0001));
    o.rgb = mix(o.rgb, shiftingResult, shiftingFade);
  }
  if (enableFrozen) {
    float luma = dot(o.rgb, vec3(0.299, 0.587, 0.114));
    vec3 desaturated = mix(o.rgb, vec3(luma), frozenDesaturation);
    o.rgb = mix(desaturated, frozenColor.rgb, frozenIntensity * 0.4);
    float shimmer = texture2D(noiseTexture, uv0 * frozenShimmerScale + cc_time.x * frozenShimmerSpeed * 0.1).r;
    shimmer = pow(shimmer, 2.0) * frozenIntensity;
    o.rgb += frozenColor.rgb * shimmer * 0.5 * originalAlpha;
  }
  if (enableFlash) {
    float elapsed = max(0.0, cc_time.x - flashStartTime);
    float flashIntensity = 0.0;
    if (flashMode < 0.5) {
      float t = clamp(1.0 - elapsed / max(flashDuration, 0.0001), 0.0, 1.0);
      flashIntensity = 1.0 - pow(1.0 - t, 4.0);
      o.rgb = mix(o.rgb, flashColor.rgb, flashColor.a * flashIntensity * originalAlpha);
    } else {
      float totalPeriod = flashDelay + flashDuration;
      float t = mod(elapsed, totalPeriod);
      float activePhase = step(flashDelay, t);
      float localTime = (t - flashDelay) * activePhase;
      float instantFlash = step(flashDuration, 0.0001);
      float fadeFlash = clamp(1.0 - localTime / max(flashDuration, 0.0001), 0.0, 1.0);
      flashIntensity = mix(fadeFlash, 1.0, instantFlash) * activePhase;
      o.rgb += flashColor.rgb * flashColor.a * flashIntensity * originalAlpha;
    }
  }
  if (enableOutline) {
    vec2 texelSize = vec2(dFdx(uv0.x), dFdy(uv0.y));
    if (length(texelSize) < 0.0001) {
      texelSize = vec2(0.005, 0.005);
    }
    vec2 destUv = vec2(outlineWidth * texelSize.x * 200.0, outlineWidth * texelSize.y * 200.0);
    if (enableOutlineDistort) {
      vec2 uvOutDist = uv0 * outlineDistortTilingOffset.xy + outlineDistortTilingOffset.zw;
      uvOutDist.x += mod(cc_time.x * outlineDistortXSpeed, 1.0);
      uvOutDist.y += mod(cc_time.x * outlineDistortYSpeed, 1.0);
      float outDistortAmnt = (texture2D(outlineDistortTexture, uvOutDist).r - 0.5) * 0.2 * outlineDistortAmount;
      destUv.x += outDistortAmnt;
      destUv.y += outDistortAmnt;
    }
    float spriteLeft = texture2D(cc_spriteTexture, uv0 + vec2(destUv.x, 0.0)).a;
    float spriteRight = texture2D(cc_spriteTexture, uv0 - vec2(destUv.x, 0.0)).a;
    float spriteBottom = texture2D(cc_spriteTexture, uv0 + vec2(0.0, destUv.y)).a;
    float spriteTop = texture2D(cc_spriteTexture, uv0 - vec2(0.0, destUv.y)).a;
    float result = spriteLeft + spriteRight + spriteBottom + spriteTop;
    float neighborMask = step(0.05, clamp(result, 0.0, 1.0));
    float innerMask = step(0.05, originalAlpha);
    result = neighborMask * (1.0 - innerMask) * outlineAlpha;
    vec4 finalOutlineColor = outlineColor;
    if (enableOutlineTex) {
      vec2 uvOutTex = uv0 * outlineTexTilingOffset.xy + outlineTexTilingOffset.zw;
      uvOutTex.x += mod(cc_time.x * outlineTexXSpeed, 1.0);
      uvOutTex.y += mod(cc_time.x * outlineTexYSpeed, 1.0);
      vec4 tempOutColor = texture2D(outlineTexture, uvOutTex);
      finalOutlineColor = tempOutColor * outlineColor;
    }
    result *= (1.0 - originalAlpha) * outlineAlpha;
    vec4 outline = finalOutlineColor * v_light.a;
    outline.rgb *= outlineGlow;
    outline.a = result;
    o = mix(o, outline, result);
  }
  ALPHA_TEST(o);
  return o;
}
